(function(){"use strict";var steps=document.querySelectorAll(".order-step");var stepIndicatorText=document.querySelector(".step-indicator-text");var stepIndicatorFill=document.querySelector(".step-indicator-fill");var stepDots=document.querySelectorAll(".step-dot");var currentStep=1;var totalSteps=4;document.querySelectorAll(".form-chip-group").forEach(function(group){var hiddenInput=document.getElementById(group.getAttribute("data-field"));function syncHidden(){var selected=[];group.querySelectorAll(".form-chip.selected").forEach(function(chip){selected.push(chip.getAttribute("data-value"))});if(hiddenInput)hiddenInput.value=selected.join(", ")}group.querySelectorAll(".form-chip").forEach(function(chip){chip.addEventListener("click",function(){var val=chip.getAttribute("data-value");if(val==="None"){group.querySelectorAll(".form-chip").forEach(function(c){c.classList.remove("selected")});chip.classList.add("selected")}else{var noneChip=group.querySelector('.form-chip[data-value="None"]');if(noneChip)noneChip.classList.remove("selected");chip.classList.toggle("selected")}syncHidden()})})});function showStep(n){steps.forEach(function(step){step.classList.remove("active")});var target=document.getElementById("step-"+n);if(target){target.classList.add("active");currentStep=n;updateIndicator();window.scrollTo({top:0,behavior:"smooth"})}}function updateIndicator(){if(currentStep<=totalSteps){stepIndicatorText.textContent="Step "+currentStep+" of "+totalSteps;stepIndicatorFill.style.width=currentStep/totalSteps*100+"%"}else{stepIndicatorText.textContent="Complete";stepIndicatorFill.style.width="100%"}stepDots.forEach(function(dot,index){dot.classList.remove("active","completed");if(index+1===currentStep){dot.classList.add("active")}else if(index+1<currentStep){dot.classList.add("completed")}})}function goNext(){if(currentStep>=totalSteps)return;if(!validateStep(currentStep))return;showStep(currentStep+1)}function goBack(){if(currentStep<=1)return;showStep(currentStep-1)}function goToStep(n){showStep(n)}document.querySelectorAll('[data-action="next"]').forEach(function(btn){btn.addEventListener("click",goNext)});document.querySelectorAll('[data-action="back"]').forEach(function(btn){btn.addEventListener("click",goBack)});document.querySelectorAll('[data-action="edit"]').forEach(function(btn){btn.addEventListener("click",function(){var targetStep=parseInt(this.getAttribute("data-target"),10);goToStep(targetStep)})});function validateStep(step){var stepEl=document.getElementById("step-"+step);if(!stepEl)return true;var requiredFields=stepEl.querySelectorAll("[required]");var valid=true;requiredFields.forEach(function(field){clearFieldError(field);if(field.type==="radio"){var name=field.name;var groupChecked=stepEl.querySelector('input[name="'+name+'"]:checked');if(!groupChecked){showFieldError(field,"Please select an option");valid=false}}else if(!field.value.trim()){showFieldError(field,"This field is required");valid=false}else if(field.type==="email"&&!isValidEmail(field.value)){showFieldError(field,"Please enter a valid email address");valid=false}});return valid}function isValidEmail(email){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)}function showFieldError(field,message){field.classList.add("error");var errorEl=field.closest(".form-group").querySelector(".form-error-message");if(errorEl){errorEl.textContent=message;errorEl.classList.add("visible")}}function clearFieldError(field){field.classList.remove("error");var errorEl=field.closest(".form-group");if(errorEl){var msg=errorEl.querySelector(".form-error-message");if(msg){msg.classList.remove("visible")}}}document.querySelectorAll(".form-input, .form-textarea, .form-select").forEach(function(field){field.addEventListener("input",function(){clearFieldError(this)})});document.querySelectorAll('input[type="radio"]').forEach(function(radio){radio.addEventListener("change",function(){var group=document.querySelector('input[name="'+this.name+'"]');if(group)clearFieldError(group)})});function populateReview(){setReviewValue("review-program","5-Day Detox Box — $2,000");var dietRadio=document.querySelector('input[name="diet"]:checked');setReviewValue("review-diet",dietRadio?dietRadio.value:"");setReviewValue("review-allergies",getFieldValue("allergies"));setReviewValue("review-chronic",getFieldValue("chronic"));setReviewValue("review-medications",getFieldValue("medications"));setReviewValue("review-dislikes",getFieldValue("dislikes"));setReviewValue("review-health-notes",getFieldValue("health-notes"));setReviewValue("review-name",getFieldValue("full-name"));setReviewValue("review-email",getFieldValue("email"));setReviewValue("review-phone",getFieldValue("phone"));setReviewValue("review-address",getFieldValue("address"));setReviewValue("review-delivery-notes",getFieldValue("delivery-notes"))}function getFieldValue(id){var field=document.getElementById(id);if(!field)return"";return field.value.trim()}function setReviewValue(id,value){var el=document.getElementById(id);if(!el)return;if(value){el.textContent=value;el.classList.remove("empty")}else{el.textContent="Not provided";el.classList.add("empty")}}var originalShowStep=showStep;showStep=function(n){if(n===4)populateReview();originalShowStep(n)};var orderForm=document.getElementById("order-form");if(orderForm){orderForm.addEventListener("submit",function(e){e.preventDefault();if(!validateStep(currentStep))return;steps.forEach(function(step){step.classList.remove("active")});var confirmation=document.getElementById("step-5");if(confirmation){confirmation.classList.add("active");currentStep=5;updateIndicator();window.scrollTo({top:0,behavior:"smooth"})}})}var faqItems=document.querySelectorAll(".faq-item");faqItems.forEach(function(item){var question=item.querySelector(".faq-question");var answer=item.querySelector(".faq-answer");question.addEventListener("click",function(){var isOpen=item.classList.contains("open");faqItems.forEach(function(otherItem){if(otherItem!==item){otherItem.classList.remove("open");var otherAnswer=otherItem.querySelector(".faq-answer");if(otherAnswer)otherAnswer.style.maxHeight=null}});if(isOpen){item.classList.remove("open");answer.style.maxHeight=null}else{item.classList.add("open");answer.style.maxHeight=answer.scrollHeight+"px"}});question.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();question.click()}})});showStep(1)})();